import 'package:cerne/core/network/failure.dart';
import 'package:cerne/features/entries/data/entries_local_cache.dart';
import 'package:cerne/features/entries/data/entries_remote_data_source.dart';
import 'package:cerne/features/entries/domain/entities/entries_page.dart';
import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:cerne/features/entries/domain/repositories/entries_repository.dart';
import 'package:cerne/features/session/domain/repositories/session_repository.dart';
import 'package:fpdart/fpdart.dart';

/// Wraps [EntriesRemoteDataSource] and owns [cachedEntries] — an in-memory
/// mirror, backed by [EntriesLocalCache], of every entry this process has
/// seen (via a successful [create]/[list]/[search]), so it survives an app
/// restart. Registered as a `get_it` `lazySingleton` so the cache survives
/// across modal opens (same lifetime pattern as RF03's `VaultRepository`).
/// Read back out for display by `RecordsBloc` when a fetch fails outright —
/// the on-device fallback the PRD's "local read cache" describes
/// (requirements.md line 50/125).
class EntriesRepositoryImpl implements EntriesRepository {
  EntriesRepositoryImpl(
    this._remoteDataSource, {
    required this._sessionRepository,
    required this._localCache,
  });

  final EntriesRemoteDataSource _remoteDataSource;
  final SessionRepository _sessionRepository;
  final EntriesLocalCache _localCache;

  final List<Entry> _cachedEntries = [];
  Future<void>? _localCacheLoad;

  // Runs once per process; every public method awaits it before touching
  // `_cachedEntries`, so the persisted cache is always merged in before
  // either a remote call resolves or `cachedEntries` is read back out —
  // closing the race between "app just launched" and "first read of the
  // cache."
  Future<void> _ensureLocalCacheLoaded() {
    return _localCacheLoad ??= _localCache.readAll().then(_mergeEntries);
  }

  void _mergeEntries(List<Entry> fetched) {
    for (final entry in fetched) {
      final index = _cachedEntries.indexWhere((e) => e.id == entry.id);
      if (index >= 0) {
        _cachedEntries[index] = entry;
      } else {
        _cachedEntries.add(entry);
      }
    }
  }

  Future<void> _cacheAndPersist(List<Entry> fetched) async {
    _mergeEntries(fetched);
    await _localCache.writeAll(_cachedEntries);
  }

  @override
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    String? chatMessageId,
    DateTime? occurredAt,
  }) async {
    await _ensureLocalCacheLoaded();
    final result = await _remoteDataSource.create(
      content: content,
      source: source,
      chatMessageId: chatMessageId,
      occurredAt: occurredAt,
    );
    return result.match(
      (failure) => Future.value(Left(failure)),
      (entry) async {
        await _cacheAndPersist([entry]);
        return Right(entry);
      },
    );
  }

  @override
  List<Entry> get cachedEntries => List.unmodifiable(_cachedEntries);

  @override
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int? limit,
  }) async {
    await _ensureLocalCacheLoaded();
    Future<Either<Failure, EntriesPage>> fetch() => _remoteDataSource.list(
      cursor: cursor,
      source: source,
      dateFrom: dateFrom,
      dateTo: dateTo,
      limit: limit,
    );
    final result = await fetch();
    final Either<Failure, EntriesPage> afterRetry = await result.match(
      (failure) => failure is AuthExpiredFailure
          ? _retryAfterSilentRefresh(fetch)
          : Future.value(Left(failure)),
      (page) => Future.value(Right(page)),
    );
    return afterRetry.match(
      (failure) => Future.value(Left(failure)),
      (page) async {
        await _cacheAndPersist(page.entries);
        return Right(page);
      },
    );
  }

  @override
  Future<Either<Failure, List<Entry>>> search({
    String? q,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int limit = 50,
  }) async {
    await _ensureLocalCacheLoaded();
    Future<Either<Failure, List<Entry>>> fetch() => _remoteDataSource.search(
      q: q,
      source: source,
      dateFrom: dateFrom,
      dateTo: dateTo,
      limit: limit,
    );
    final result = await fetch();
    final Either<Failure, List<Entry>> afterRetry = await result.match(
      (failure) => failure is AuthExpiredFailure
          ? _retryAfterSilentRefresh(fetch)
          : Future.value(Left(failure)),
      (entries) => Future.value(Right(entries)),
    );
    return afterRetry.match(
      (failure) => Future.value(Left(failure)),
      (entries) async {
        await _cacheAndPersist(entries);
        return Right(entries);
      },
    );
  }

  @override
  Future<Either<Failure, Entry>> getById(String id) async {
    final result = await _remoteDataSource.getById(id);
    return result.match(
      (failure) => failure is AuthExpiredFailure
          ? _retryAfterSilentRefresh(() => _remoteDataSource.getById(id))
          : Future.value(Left(failure)),
      (entry) => Future.value(Right(entry)),
    );
  }

  // Exactly one retry. If it also comes back `AuthExpiredFailure` (a
  // pathological double-expiry), that is returned as-is — no second refresh
  // attempt, no loop (research.md R4, contracts/entries-repository-extension.md).
  Future<Either<Failure, T>> _retryAfterSilentRefresh<T>(
    Future<Either<Failure, T>> Function() retry,
  ) async {
    final refreshed = await _sessionRepository.refresh();
    return refreshed.match(
      (_) => Future.value(
        const Left(
          AuthExpiredFailure(message: 'Session could not be renewed', requestId: ''),
        ),
      ),
      (_) => retry(),
    );
  }
}

import 'dart:convert';

import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// On-device, cross-restart persistence for the entries the user has
/// already seen (the PRD's "local read cache" — requirements.md line 50/125:
/// results from it stay visible offline and reconcile with the server on
/// reconnect, with no duplicates). Keychain-backed, same pattern as
/// `VaultSecureStorage` — journal content is personal data, so it stays
/// encrypted at rest like the PIN it already sits behind.
///
/// Distinct from `EntriesRepositoryImpl`'s in-memory `cachedEntries`: that
/// field only ever held optimistic just-created entries for this process's
/// lifetime (research.md R8, 003-multimodal-capture). This class is what
/// makes that same list survive an app restart, which is what a cold open
/// on an already-offline device needs (closing snapshot at unit completion
/// did not cover this path — see Meus Registros intervention report).
class EntriesLocalCache {
  EntriesLocalCache({FlutterSecureStorage? storage})
    : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _key = 'entriesLocalCache';

  Future<List<Entry>> readAll() async {
    final raw = await _storage.read(key: _key);
    if (raw == null) return const [];
    try {
      final decoded = jsonDecode(raw) as List<dynamic>;
      return decoded.map((e) => _fromJson(e as Map<String, dynamic>)).toList();
    } on FormatException {
      return const [];
    } on TypeError {
      return const [];
    }
  }

  Future<void> writeAll(List<Entry> entries) {
    final encoded = jsonEncode(entries.map(_toJson).toList());
    return _storage.write(key: _key, value: encoded);
  }

  Map<String, dynamic> _toJson(Entry e) => {
    'id': e.id,
    'content': e.content,
    'source': e.source.name,
    'chatMessageId': e.chatMessageId,
    'occurredAt': e.occurredAt.toUtc().toIso8601String(),
    'tags': [
      for (final tag in e.tags) {'id': tag.id, 'name': tag.name},
    ],
    'piiStatus': e.piiStatus.name,
    'piiSpans': [
      for (final span in e.piiSpans)
        {'start': span.start, 'end': span.end, 'type': span.type},
    ],
    'embeddingStatus': e.embeddingStatus.name,
    'mediaDurationSeconds': e.mediaDurationSeconds,
    'serverRevision': e.serverRevision,
    'createdAt': e.createdAt.toUtc().toIso8601String(),
    'updatedAt': e.updatedAt.toUtc().toIso8601String(),
    'similarity': e.similarity,
  };

  Entry _fromJson(Map<String, dynamic> data) => Entry(
    id: data['id'] as String,
    content: data['content'] as String,
    source: EntrySource.values.byName(data['source'] as String),
    chatMessageId: data['chatMessageId'] as String?,
    occurredAt: DateTime.parse(data['occurredAt'] as String),
    tags: (data['tags'] as List<dynamic>)
        .map(
          (t) => EntryTag(
            id: (t as Map<String, dynamic>)['id'] as String,
            name: t['name'] as String,
          ),
        )
        .toList(),
    piiStatus: PiiStatus.values.byName(data['piiStatus'] as String),
    piiSpans: (data['piiSpans'] as List<dynamic>)
        .map(
          (s) => PiiSpan(
            start: (s as Map<String, dynamic>)['start'] as int,
            end: s['end'] as int,
            type: s['type'] as String,
          ),
        )
        .toList(),
    embeddingStatus: EmbeddingStatus.values.byName(
      data['embeddingStatus'] as String,
    ),
    mediaDurationSeconds: data['mediaDurationSeconds'] as int?,
    serverRevision: data['serverRevision'] as int,
    createdAt: DateTime.parse(data['createdAt'] as String),
    updatedAt: DateTime.parse(data['updatedAt'] as String),
    similarity: (data['similarity'] as num?)?.toDouble(),
  );
}

import 'package:cerne/core/network/failure.dart';
import 'package:cerne/features/entries/domain/entities/entries_page.dart';
import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:fpdart/fpdart.dart';

/// The shared seam research.md R8 builds because requirements.md §RF10
/// already names it (contracts/entries-repository.md). Registered as a
/// `get_it` `lazySingleton` so [cachedEntries] survives across modal opens
/// (same lifetime pattern as RF03's `VaultRepository`).
abstract class EntriesRepository {
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    String? chatMessageId,
    DateTime? occurredAt,
  });

  /// FR-011's "local entries store/cache" — every entry this app has ever
  /// successfully fetched or created, backed by on-device persistence so it
  /// survives a restart. `RecordsBloc` reads this back out as the offline
  /// fallback when a fetch fails outright (the PRD's "local read cache",
  /// requirements.md line 50/125).
  List<Entry> get cachedEntries;

  /// `GET /entries` (`entries-list`), paginated newest-occurred-first.
  /// Retries exactly once through `SessionRepository.refresh()` on
  /// `AuthExpiredFailure` before giving up (research.md R4).
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int? limit,
  });

  /// `GET /entries/:id` (`entries-get`). Implemented and tested; no call
  /// site in this unit's UI flow (research.md R7).
  Future<Either<Failure, Entry>> getById(String id);

  /// `GET /entries/search` (`entries-search`) — bounded, no cursor
  /// (FR-005b). Retries exactly once through `SessionRepository.refresh()`
  /// on `AuthExpiredFailure`, same as `list()`/`getById()`.
  Future<Either<Failure, List<Entry>>> search({
    String? q,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int limit = 50,
  });
}

