22	    final raw = await _storage.read(key: _sessionsKey);
23	    if (raw == null) return const [];
24	    try {
25	      final decoded = jsonDecode(raw) as List<dynamic>;
26	      return decoded
27	          .map((e) => _sessionFromJson(e as Map<String, dynamic>))
28	          .toList();
29	    } on FormatException {
30	      return const [];
31	    } on TypeError {
32	      return const [];
33	    }
34	  }
