37	    final encoded = jsonEncode(sessions.map(_sessionToJson).toList());
38	    return _storage.write(key: _sessionsKey, value: encoded);
39	  }
40	
41	  Future<Map<String, List<ChatMessage>>> readAllMessages() async {
42	    final raw = await _storage.read(key: _messagesKey);
43	    if (raw == null) return const {};
44	    try {
45	      final decoded = jsonDecode(raw) as Map<String, dynamic>;
46	      return decoded.map(
47	        (sessionId, messages) => MapEntry(
48	          sessionId,
49	          (messages as List<dynamic>)
50	              .map((m) => _messageFromJson(m as Map<String, dynamic>))
51	              .toList(),
52	        ),
