67	    final encoded = jsonEncode(
68	      updated.map(
69	        (sid, msgs) => MapEntry(sid, msgs.map(_messageToJson).toList()),
70	      ),
71	    );
72	    await _storage.write(key: _messagesKey, value: encoded);
73	  }
