170	  void _onLocalCacheRefreshed(
171	    RecordsLocalCacheRefreshed event,
172	    Emitter<RecordsState> emit,
173	  ) {
174	    final current = state;
175	    if (current is! RecordsLoaded || current.hasAnyActiveCriteria) return;
176	    emit(
177	      current.copyWith(
178	        entries: EntryMerger.merge(
179	          primary: current.entries,
180	          secondary: _entriesRepository.cachedEntries,
181	        ),
182	      ),
183	    );
184	  }
