186	  // --- Search text -> debounce -> fetch (FR-001/FR-002, research.md R4/R6) ---
187	
188	  Future<void> _onSearchTextChanged(SearchTextChanged event, Emitter<RecordsState> emit) async {
189	    _debounceTimer?.cancel();
190	    _query = event.text;
191	    if (event.text.isEmpty) {
192	      // Acceptance Scenario 3 / Edge Case: no request for empty text —
193	      // refetch immediately under whatever filters are still active.
194	      await _fetchForCriteria(emit);
195	      return;
