11	/// One new instance per `showModalBottomSheet` call (`registerFactory`,
12	/// research.md R6) — never reused across sheet opens. Depends only on
13	/// [ExportRepository]/[ExportFileRepository] — never `SessionRepository`,
14	/// never `RecordsBloc` or any of its event/state types.
15	class ExportBloc extends Bloc<ExportEvent, ExportState> {
16	  ExportBloc({
17	    required ExportRepository exportRepository,
18	    required ExportFileRepository exportFileRepository,
19	    // Not part of the public contract's constructor shape (data-model.md) —
20	    // overridable only for test speed, the same role `RecordsBloc`'s own
21	    // `debounceDuration` plays (research.md R3).
22	    Duration pollInterval = const Duration(seconds: 2),
23	  }) : _exportRepository = exportRepository, // ignore: prefer_initializing_formals
24	       _exportFileRepository = exportFileRepository, // ignore: prefer_initializing_formals
25	       _pollInterval = pollInterval, // ignore: prefer_initializing_formals
26	       super(const ExportPending()) {
27	    on<ExportRequested>(_onExportRequested);
28	    on<ExportStatusPollTicked>(_onStatusPollTicked);
29	    on<PdfDownloadRequested>(_onPdfDownloadRequested);
30	    on<RawDataDownloadRequested>(_onRawDataDownloadRequested);
31	  }
32	
33	  final ExportRepository _exportRepository;
34	  final ExportFileRepository _exportFileRepository;
35	  final Duration _pollInterval;
36	  final _reauthController = StreamController<void>.broadcast();
37	
38	  String? _jobId;
39	  Timer? _pollTimer;
40	
41	  /// A one-shot side effect, not a state (research.md R7) — `ExportSheet`
42	  /// listens to this to raise the "Sessão expirada" overlay.
43	  Stream<void> get reauthRequired => _reauthController.stream;
44	
45	  Future<void> _onExportRequested(ExportRequested event, Emitter<ExportState> emit) async {
46	    emit(const ExportPending());
47	    final result = await _exportRepository.create(
48	      periodStart: event.periodStart,
49	      periodEnd: event.periodEnd,
50	    );
51	    result.match(
52	      (failure) {
53	        if (failure is ExportEmptyPeriodFailure) {
54	          emit(const ExportEmptyPeriod());
55	          return;
56	        }
57	        if (failure is AuthExpiredFailure) {
58	          _reauthController.add(null);
59	        }
